import { NextRequest, NextResponse } from "next/server";
import { prisma } from "@/lib/prisma";
import { imageVersionMatches, verifyImageSignature } from "@/lib/image-url";
import { ImageValidationError, normalizeImageData } from "@/lib/image-validation";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

type Ctx = { params: Promise<{ kind: string; id: string; index: string }> };

/**
 * Serves a stored data-URL image as a normal image response.
 * Access is granted by the short-lived signature generated by the list APIs,
 * so <img> tags do not need to send the app's Authorization header.
 */
export async function GET(request: NextRequest, { params }: Ctx) {
  const { kind, id, index: indexRaw } = await params;
  const index = Number(indexRaw);
  if (!Number.isInteger(index) || index < 0) {
    return new NextResponse("Not found", { status: 404 });
  }

  const { searchParams } = new URL(request.url);
  const version = searchParams.get("v") || "";
  const exp = Number(searchParams.get("exp") || 0);
  const sig = searchParams.get("sig") || "";
  if (!verifyImageSignature(kind, id, index, version, exp, sig)) {
    return new NextResponse("Forbidden", { status: 403 });
  }

  try {
    let source: string | null = null;

    if (kind === "item") {
      if (index !== 0) return new NextResponse("Not found", { status: 404 });
      const item = await prisma.item.findUnique({ where: { id }, select: { imageUrl: true } });
      source = item?.imageUrl || null;
    } else if (kind === "report") {
      const report = await prisma.report.findUnique({
        where: { id },
        select: { imageUrl: true, imageUrls: true },
      });
      if (!report) return new NextResponse("Not found", { status: 404 });
      source = Array.isArray(report.imageUrls) && report.imageUrls[index]
        ? report.imageUrls[index]
        : index === 0
          ? report.imageUrl
          : null;
    } else if (kind === "claim") {
      const claim = await prisma.claim.findUnique({
        where: { id },
        select: { evidenceImageUrl: true, evidenceImageUrls: true },
      });
      if (!claim) return new NextResponse("Not found", { status: 404 });
      source = Array.isArray(claim.evidenceImageUrls) && claim.evidenceImageUrls[index]
        ? claim.evidenceImageUrls[index]
        : index === 0
          ? claim.evidenceImageUrl
          : null;
    } else {
      return new NextResponse("Not found", { status: 404 });
    }

    if (!source) return new NextResponse("Not found", { status: 404 });

    // A signed URL for an old image must not authorize its replacement.
    if (!imageVersionMatches(source, version)) return new NextResponse("Not found", { status: 404 });
    // Do not redirect to untrusted stored URLs or pass legacy MIME types through.
    // Sanitizing on read also protects photos saved before upload validation.
    const { buffer, mime } = await normalizeImageData(source);
    return new NextResponse(new Uint8Array(buffer), {
      headers: {
        "Content-Type": mime,
        "Content-Length": String(buffer.length),
        "Content-Disposition": 'inline; filename="photo.webp"',
        "Cache-Control": "private, no-store, max-age=0",
        "Content-Security-Policy": "default-src 'none'; sandbox",
        "Cross-Origin-Resource-Policy": "same-origin",
        "Referrer-Policy": "no-referrer",
        "X-Content-Type-Options": "nosniff",
      },
    });
  } catch (error) {
    if (error instanceof ImageValidationError) return new NextResponse("Unsupported image", { status: 415, headers: { "Cache-Control": "private, no-store" } });
    console.error("Image fetch failed", error);
    return new NextResponse("Failed to load image", { status: 500 });
  }
}
